    guardian = VaultGuardian()
    print("Welcome to the secure AI system. To access the vault, you must provide the correct password.")
    user_input = input("Enter the password: ")
    response = guardian.check_password(user_input)
    print(response)
    print(guardian.get_status())

if __name__ == "__main__":
    main()
